import"./MainLayout.astro_astro_type_script_index_0_lang.B_H427wd.js";const n=document.getElementById("reg-form"),t=document.getElementById("error-msg"),r=document.getElementById("error-text"),s=document.getElementById("btn-label"),a=document.getElementById("btn-loading");localStorage.getItem("gab_token")&&(location.href="/home");n.addEventListener("submit",async d=>{d.preventDefault(),t.classList.add("hidden"),s.classList.add("hidden"),a.classList.remove("hidden");const i=Object.fromEntries(new FormData(n));try{const o=await fetch("/api/auth/register",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(i)}),e=await o.json();if(!o.ok){r.textContent=e.error||"Erro ao criar conta.",t.classList.remove("hidden");return}localStorage.setItem("gab_token",e.token),localStorage.setItem("gab_user",JSON.stringify(e.user)),location.href="/home"}catch{r.textContent="Sem conexão com o servidor.",t.classList.remove("hidden")}finally{s.classList.remove("hidden"),a.classList.add("hidden")}});
